from pathlib import Path
p=Path('tests/course-data-validation.test.ts')
s=p.read_text()
old="""const courseModules = import.meta.glob('../src/courses/data/*.ts', {
  eager: true,
  import: 'default',
}) as Record<string, Course>;

const courses = Object.entries(courseModules)
  .map(([path, course]) => ({ path, course }))
  .sort((a, b) => a.path.localeCompare(b.path));
"""
new="""const courseModules = import.meta.glob('../src/courses/data/*.ts', { eager: true }) as Record<
  string,
  Record<string, unknown>
>;

const courses = Object.entries(courseModules)
  .map(([path, module]) => {
    const candidates = Object.values(module).filter(
      (value): value is Course =>
        typeof value === 'object' &&
        value !== null &&
        'id' in value &&
        'holes' in value &&
        Array.isArray((value as Course).holes),
    );

    expect(
      candidates.length,
      `${path}: expected exactly one exported Course descriptor, found ${candidates.length}`,
    ).toBe(1);

    return { path, course: candidates[0]! };
  })
  .sort((a, b) => a.path.localeCompare(b.path));
"""
if old not in s:
    raise SystemExit('target block not found')
p.write_text(s.replace(old,new))
PY
npx vitest run tests/course-data-validation.test.ts
